export const enum ParseError {
  OK = 0,
  BAD_MAGIC = 1,
  BAD_VERSION = 2,
  BAD_LENGTH = 3,
}

export interface ParseResult {
  frames: Frame[];
  consumed: number;
  error: ParseError;
}

/**
 * Walks a byte buffer and pops every complete frame.
 *
 * Identical for a TCP stream, a WebSocket binary message, an HTTP body and a
 * decoded SSE line: each is just bytes that happen to contain N frames. The
 * caller keeps any trailing partial frame (`consumed` says how much was used).
 */
export function parseFrames(buf: Uint8Array): ParseResult {
  const frames: Frame[] = [];
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  let off = 0;
  while (buf.length - off >= HEADER_BYTES) {
    if (dv.getUint8(off) !== MAGIC0 || dv.getUint8(off + 1) !== MAGIC1) {
      return { frames, consumed: off, error: ParseError.BAD_MAGIC };
    }
    if (dv.getUint8(off + 2) !== PROTOCOL_VERSION) {
      return { frames, consumed: off, error: ParseError.BAD_VERSION };
    }
    const type = dv.getUint8(off + 3);
    const len = dv.getUint16(off + 4, true);
    const seq = dv.getUint16(off + 6, true);
    if (len > C.MAX_FRAME_BYTES) {
      return { frames, consumed: off, error: ParseError.BAD_LENGTH };
    }
    const expected = PAYLOAD_BYTES[type];
    if (expected !== undefined && len !== expected) {
      return { frames, consumed: off, error: ParseError.BAD_LENGTH };
    }
    if (buf.length - off - HEADER_BYTES < len) break; // partial tail, wait for more
    frames.push({ type, seq, payloadOff: off + HEADER_BYTES, payloadLen: len, buf });
    off += HEADER_BYTES + len;
  }
  return { frames, consumed: off, error: ParseError.OK };
}

/** Concatenates encoded frames into one buffer (an HTTP body, a WS message). */
export function concatFrames(frames: Uint8Array[]): Uint8Array<ArrayBuffer> {
  let n = 0;
  for (const f of frames) n += f.length;
  const out = new Uint8Array(n);
  let o = 0;
  for (const f of frames) { out.set(f, o); o += f.length; }
  return out;
}

/** Fixed-width name/room fields are NUL-padded ASCII. */
export function padBytes(s: string, len: number): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(len);
  const enc = new TextEncoder().encode(s);
  out.set(enc.subarray(0, len));
  return out;
}

export function unpadBytes(b: Uint8Array): string {
  let end = b.length;
  while (end > 0 && b[end - 1] === 0) end--;
  return new TextDecoder().decode(b.subarray(0, end));
}
